def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Bottom-row 5s identify columns whose zeroes are filled by the nearest
    # nonzero cell below, extending each lower marker upward.
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        seeds = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        for r in range(h):
            if grid[r][c] != 0:
                continue
            below = next(((sr, color) for sr, color in seeds if sr > r), None)
            if below is not None:
                out[r][c] = below[1]
            elif seeds:
                out[r][c] = seeds[-1][1]
    return out
